def search_pubmed_key_words(key_words, num_results=None, **_extra):
    import json, os, datetime, time, re, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _today_utc():
        return datetime.datetime.utcnow().date()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and c.get("id")]
        if not actives:
            return None
        actives.sort(key=lambda r: (r.get("created_at") or "", r.get("id")))
        return actives[0]

    t0 = time.time()

    # Validate inputs
    if not isinstance(key_words, str) or not key_words.strip():
        return _err("VALIDATION_ERROR", "key_words must be a non-empty string.")
    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int) or num_results <= 0:
        return _err("VALIDATION_ERROR", "num_results must be a positive integer.")
    if num_results > 500:
        # API accepts larger? Schema caps persisted retmax; requested num_results constraint is 1..500
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 500.")

    clients = _load("api_clients.json")
    client = _pick_active_client(clients)
    if not client:
        return _err("UNAUTHORIZED", "No active client context is available to serve this request.")

    # Enforce client status rule (already active) - if somehow not:
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.")

    # Quota: daily_search_limit based on search_requests created today for both search tools
    sreqs = _load("search_requests.json")
    today = _today_utc()
    created_today = 0
    for r in sreqs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client["id"]:
            continue
        if r.get("tool_name") not in ("search_pubmed_key_words", "search_pubmed_advanced"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt and dt.date() == today:
            created_today += 1
    limit = client.get("daily_search_limit")
    if isinstance(limit, int) and created_today >= limit:
        return _err("RATE_LIMIT", "Daily search quota exceeded.", limit=limit, used=created_today)

    # Create search_request row (queued)
    now = _now_iso()
    req_id = _gen_id("srch")
    normalized_query = key_words.strip()
    pubmed_retmax = min(int(num_results), 500)
    req_row = {
        "id": req_id,
        "client_id": client["id"],
        "tool_name": "search_pubmed_key_words",
        "key_words": key_words,
        "term": None,
        "title": None,
        "author": None,
        "journal": None,
        "start_date": None,
        "end_date": None,
        "num_results": int(num_results),
        "normalized_query": normalized_query,
        "status": "queued",
        "pubmed_retmax": int(pubmed_retmax),
        "pubmed_webenv": None,
        "pubmed_query_key": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    sreqs.append(req_row)
    _save("search_requests.json", sreqs)

    # Transition queued -> running
    req_row["status"] = "running"
    req_row["updated_at"] = _now_iso()
    _save("search_requests.json", sreqs)

    # Call PubMed ESearch
    pmids = []
    webenv = None
    query_key = None
    try:
        params = {
            "db": "pubmed",
            "term": normalized_query,
            "retmode": "json",
            "retmax": str(pubmed_retmax),
            "usehistory": "y",
        }
        url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?" + urllib.parse.urlencode(params)
        with urllib.request.urlopen(url, timeout=20) as resp:
            body = resp.read().decode("utf-8", "replace")
        data = json.loads(body)
        esr = (data or {}).get("esearchresult") or {}
        idlist = esr.get("idlist") or []
        if not isinstance(idlist, list):
            idlist = []
        pmids = [str(x) for x in idlist if re.fullmatch(r"[0-9]+", str(x) or "")]
        webenv = esr.get("webenv")
        query_key = esr.get("querykey")
        # Some responses use "querykey" string; keep as-is
        if webenv is not None and not isinstance(webenv, str):
            webenv = str(webenv)
        if query_key is not None and not isinstance(query_key, str):
            query_key = str(query_key)
    except Exception as e:
        # Transition running -> failed
        req_row["status"] = "failed"
        req_row["error_code"] = "UPSTREAM_ERROR"
        req_row["error_message"] = str(e)
        req_row["updated_at"] = _now_iso()
        _save("search_requests.json", sreqs)
        return _err("UPSTREAM_ERROR", "PubMed search failed.", detail=str(e), search_request_id=req_id)

    # Persist results
    sresults = _load("search_results.json")
    # ensure uniqueness constraints within this request
    existing_pairs = {(r.get("search_request_id"), r.get("pmid")) for r in sresults if isinstance(r, dict)}
    existing_ranks = {(r.get("search_request_id"), r.get("rank")) for r in sresults if isinstance(r, dict)}
    now2 = _now_iso()
    stored = 0
    for i, pmid in enumerate(pmids[:pubmed_retmax], start=1):
        if (req_id, pmid) in existing_pairs or (req_id, i) in existing_ranks:
            continue
        sresults.append(
            {
                "id": _gen_id("sres"),
                "search_request_id": req_id,
                "pmid": pmid,
                "rank": i,
                "created_at": now2,
                "updated_at": now2,
            }
        )
        stored += 1
    if stored:
        _save("search_results.json", sresults)

    # Transition running -> succeeded
    req_row["status"] = "succeeded"
    req_row["pubmed_webenv"] = webenv
    req_row["pubmed_query_key"] = query_key
    req_row["updated_at"] = _now_iso()
    _save("search_requests.json", sreqs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": req_row,
        "results": [{"pmid": r["pmid"], "rank": r["rank"]} for r in sorted(
            [r for r in sresults if isinstance(r, dict) and r.get("search_request_id") == req_id],
            key=lambda x: x.get("rank", 10**9),
        )][:pubmed_retmax],
        "meta": {
            "requested": int(num_results),
            "returned": min(len(pmids), pubmed_retmax),
            "stored": stored,
            "latency_ms": latency_ms,
        },
    }

def search_pubmed_advanced(term=None, title=None, author=None, journal=None, start_date=None, end_date=None, num_results=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    today = now_dt.date()

    def _audit(status_code, client_id=None, error=None):
        # Best-effort audit; never blocks response
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{os.urandom(3).hex()}",
                "endpoint": "search_pubmed_advanced",
                "client_id": client_id,
                "credential": None,
                "status": status_code,
                "error": error,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _parse_date(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "INVALID"
        s2 = s.strip()
        if not s2:
            return None
        try:
            # Enforce YYYY-MM-DD
            return datetime.date.fromisoformat(s2)
        except Exception:
            return "INVALID"

    def _norm_text(x):
        if x is None:
            return None
        if not isinstance(x, str):
            return "INVALID"
        v = x.strip()
        return v if v else None

    def _gen_id(prefix, rows):
        # Deterministic-ish, collision resistant within file
        existing = set()
        for r in rows if isinstance(rows, list) else []:
            if isinstance(r, dict) and isinstance(r.get("id"), str):
                existing.add(r["id"])
        for _ in range(10):
            cand = f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"
            if cand not in existing:
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000, 9999)}"

    # ---- Validate inputs (relaxed to match schema) ----
    if num_results is None:
        num_results = 10
    if isinstance(num_results, bool) or not isinstance(num_results, int):
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "num_results must be an integer"})
        return _err("VALIDATION_ERROR", "num_results must be an integer")
    if not (1 <= num_results <= 500):
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "num_results must be between 1 and 500"})
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 500")

    term_n = _norm_text(term)
    title_n = _norm_text(title)
    author_n = _norm_text(author)
    journal_n = _norm_text(journal)

    if "INVALID" in (term_n, title_n, author_n, journal_n):
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "term/title/author/journal must be strings or null"})
        return _err("VALIDATION_ERROR", "term/title/author/journal must be strings or null")

    sd = _parse_date(start_date)
    ed = _parse_date(end_date)
    if sd == "INVALID":
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "start_date must be a parseable YYYY-MM-DD date string or null", "start_date": start_date})
        return _err("VALIDATION_ERROR", "start_date must be a parseable YYYY-MM-DD date string or null", start_date=start_date)
    if ed == "INVALID":
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "end_date must be a parseable YYYY-MM-DD date string or null", "end_date": end_date})
        return _err("VALIDATION_ERROR", "end_date must be a parseable YYYY-MM-DD date string or null", end_date=end_date)
    if sd and ed and sd > ed:
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "start_date must be on or before end_date", "start_date": start_date, "end_date": end_date})
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date", start_date=start_date, end_date=end_date)

    # NOTE: Parameter schema allows all query fields null; do NOT reject that.
    # Build a normalized query string anyway (must be non-empty per schema).
    parts = []
    if term_n:
        parts.append(f"({term_n})")
    if title_n:
        parts.append(f"({title_n}[Title])")
    if author_n:
        parts.append(f"({author_n}[Author])")
    if journal_n:
        parts.append(f"({journal_n}[Journal])")
    if sd or ed:
        s = sd.isoformat() if sd else "1000-01-01"
        e = ed.isoformat() if ed else today.isoformat()
        parts.append(f'("{s}"[Date - Publication] : "{e}"[Date - Publication])')
    normalized_query = " AND ".join(parts).strip()
    if not normalized_query:
        normalized_query = "*:*"  # non-empty sentinel query used by this local backend

    # ---- Resolve an active client that can serve the call ----
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []

    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and c.get("id")]
    if not active_clients:
        _audit("error", None, {"code": "UNAUTHORIZED", "message": "No active client available to serve request"})
        return _err("UNAUTHORIZED", "No active client available to serve request")

    sreqs = _load("search_requests.json")
    if not isinstance(sreqs, list):
        sreqs = []

    def _created_today(row):
        if not isinstance(row, dict):
            return False
        ts = row.get("created_at")
        if not isinstance(ts, str) or not ts:
            return False
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            return dt.date() == today
        except Exception:
            return False

    picked = None
    for c in active_clients:
        limit = c.get("daily_search_limit")
        if not isinstance(limit, int) or limit < 0:
            continue
        used = 0
        cid = c.get("id")
        for r in sreqs:
            if isinstance(r, dict) and r.get("client_id") == cid and _created_today(r) and r.get("tool_name") in ("search_pubmed_key_words", "search_pubmed_advanced"):
                used += 1
        if used < limit:
            picked = c
            break

    if picked is None:
        # All active clients are quota exhausted
        _audit("error", None, {"code": "QUOTA_EXCEEDED", "message": "Daily search quota exceeded for all active clients"})
        return _err("QUOTA_EXCEEDED", "Daily search quota exceeded")

    client_id = picked["id"]

    # ---- Create search_request (queued) ----
    pubmed_retmax = min(500, num_results)
    sreq_id = _gen_id("pmc_sreq", sreqs)
    sreq_row = {
        "id": sreq_id,
        "client_id": client_id,
        "tool_name": "search_pubmed_advanced",
        "key_words": None,
        "term": term_n,
        "title": title_n,
        "author": author_n,
        "journal": journal_n,
        "start_date": sd.isoformat() if sd else None,
        "end_date": ed.isoformat() if ed else None,
        "num_results": int(num_results),
        "normalized_query": normalized_query,
        "status": "queued",
        "pubmed_retmax": int(pubmed_retmax),
        "pubmed_webenv": None,
        "pubmed_query_key": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    sreqs.append(sreq_row)
    _save("search_requests.json", sreqs)

    # ---- Transition queued -> running ----
    sreq_row["status"] = "running"
    sreq_row["updated_at"] = now
    _save("search_requests.json", sreqs)

    # ---- "Execute" search: offline backend uses deterministic sample PMIDs ----
    # Prefer PMIDs already present in articles cache; fallback to prior search_results.
    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []
    pmids = []
    for a in articles:
        if isinstance(a, dict):
            pm = a.get("pmid")
            if isinstance(pm, str) and re.fullmatch(r"[0-9]+", pm or ""):
                pmids.append(pm)
    if not pmids:
        sresults_existing = _load("search_results.json")
        if isinstance(sresults_existing, list):
            for r in sresults_existing:
                if isinstance(r, dict):
                    pm = r.get("pmid")
                    if isinstance(pm, str) and re.fullmatch(r"[0-9]+", pm or ""):
                        pmids.append(pm)
    # Unique while preserving order
    seen = set()
    pmids_u = []
    for pm in pmids:
        if pm not in seen:
            seen.add(pm)
            pmids_u.append(pm)

    # Deterministic shuffle based on query + client to vary results
    rng = random.Random((normalized_query + "|" + client_id)[:256])
    rng.shuffle(pmids_u)
    selected = pmids_u[:pubmed_retmax]

    # ---- Persist search_results, contiguous 1-based rank ----
    sresults = _load("search_results.json")
    if not isinstance(sresults, list):
        sresults = []

    # Enforce uniqueness: (search_request_id, pmid) and (search_request_id, rank)
    existing_pairs = set()
    existing_ranks = set()
    for r in sresults:
        if isinstance(r, dict) and r.get("search_request_id") == sreq_id:
            if isinstance(r.get("pmid"), str):
                existing_pairs.add(r["pmid"])
            if isinstance(r.get("rank"), int):
                existing_ranks.add(r["rank"])

    created = 0
    for i, pm in enumerate(selected, start=1):
        if pm in existing_pairs or i in existing_ranks:
            continue
        sresults.append({
            "id": _gen_id("pmc_sres", sresults),
            "search_request_id": sreq_id,
            "pmid": pm,
            "rank": i,
            "created_at": now,
            "updated_at": now
        })
        created += 1

    if created:
        _save("search_results.json", sresults)

    # ---- Transition running -> succeeded (or failed if no data source) ----
    if selected is not None:
        sreq_row["status"] = "succeeded"
        sreq_row["updated_at"] = now
        sreq_row["error_code"] = None
        sreq_row["error_message"] = None
    else:
        sreq_row["status"] = "failed"
        sreq_row["updated_at"] = now
        sreq_row["error_code"] = "OFFLINE_NO_DATA"
        sreq_row["error_message"] = "No local data available to produce search results."
    _save("search_requests.json", sreqs)

    resp_results = []
    for i, pm in enumerate(selected, start=1):
        resp_results.append({"pmid": pm, "rank": i})

    _audit("ok", client_id, None)
    return {
        "search_request": sreq_row,
        "results": resp_results,
        "count": len(resp_results),
        "num_results_requested": int(num_results),
        "pubmed_retmax": int(pubmed_retmax)
    }

def get_pubmed_article_metadata(pmid, **_extra):
    import json, os, datetime, time, re, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _today_utc():
        return datetime.datetime.utcnow().date()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and c.get("id")]
        if not actives:
            return None
        actives.sort(key=lambda r: (r.get("created_at") or "", r.get("id")))
        return actives[0]

    def _norm_pmid(x):
        if isinstance(x, int):
            if x <= 0:
                return None
            return str(x)
        if isinstance(x, str):
            s = x.strip()
            if not s:
                return None
            s2 = re.sub(r"\D", "", s)
            return s2 if s2 else None
        return None

    # Freshness window (hours)
    FRESH_HOURS = 24

    pmid_n = _norm_pmid(pmid)
    if not pmid_n or not re.fullmatch(r"[0-9]+", pmid_n):
        return _err("VALIDATION_ERROR", "pmid must be a valid PubMed identifier (digits-only).")

    clients = _load("api_clients.json")
    client = _pick_active_client(clients)
    if not client:
        return _err("UNAUTHORIZED", "No active client context is available to serve this request.")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.")

    articles = _load("articles.json")
    existing = None
    for a in articles:
        if isinstance(a, dict) and a.get("pmid") == pmid_n:
            existing = a
            break

    # If cached and fresh, return without upstream call (no quota impact)
    if existing and existing.get("status") == "available":
        lf = _parse_dt(existing.get("last_fetched_at"))
        if lf:
            age = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - lf).total_seconds()
            if age <= FRESH_HOURS * 3600:
                return {"article": existing, "meta": {"cached": True, "upstream_called": False}}

    # Quota: daily_metadata_limit counts upstream calls (only when we actually call upstream)
    today = _today_utc()
    pdfs = _load("pdf_downloads.json")  # not used; keep minimal reads
    # Determine upstream calls made today by looking at articles with last_fetched_at today and updated_at ~= last_fetched_at?
    # Store does not include explicit log; approximate by counting successful fetches today (available with last_fetched_at today)
    upstream_calls_today = 0
    for a in articles:
        if not isinstance(a, dict):
            continue
        lf = _parse_dt(a.get("last_fetched_at"))
        if lf and lf.date() == today:
            upstream_calls_today += 1
    limit = client.get("daily_metadata_limit")
    if isinstance(limit, int) and upstream_calls_today >= limit:
        return _err("RATE_LIMIT", "Daily metadata fetch quota exceeded.", limit=limit, used=upstream_calls_today)

    # Fetch upstream via ESummary (metadata) + EFetch for abstract if possible
    try:
        # ESummary
        params = {"db": "pubmed", "id": pmid_n, "retmode": "json"}
        url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?" + urllib.parse.urlencode(params)
        with urllib.request.urlopen(url, timeout=20) as resp:
            body = resp.read().decode("utf-8", "replace")
        summ = json.loads(body) or {}
        result = (summ.get("result") or {})
        uids = result.get("uids") or []
        if not uids:
            # PMID not found in PubMed
            if existing:
                existing["status"] = "fetch_failed"
                existing["updated_at"] = _now_iso()
                _save("articles.json", articles)
            return _err("NOT_FOUND", "PMID not found in PubMed.", pmid=pmid_n)

        rec = result.get(pmid_n) or result.get(str(uids[0])) or {}
        if not isinstance(rec, dict) or not rec:
            if existing:
                existing["status"] = "fetch_failed"
                existing["updated_at"] = _now_iso()
                _save("articles.json", articles)
            return _err("UPSTREAM_ERROR", "Unexpected PubMed response format.", pmid=pmid_n)

        # Basic normalization
        title = rec.get("title")
        journal = (rec.get("fulljournalname") or rec.get("source") or rec.get("journalname"))
        pubdate_raw = rec.get("pubdate")
        # attempt YYYY-MM-DD from pubdate
        publication_date = None
        if isinstance(pubdate_raw, str):
            m = re.match(r"^\s*(\d{4})(?:\s+([A-Za-z]{3,9}))?(?:\s+(\d{1,2}))?", pubdate_raw.strip())
            if m:
                y = int(m.group(1))
                mon_s = (m.group(2) or "").lower()
                d_s = m.group(3)
                mon_map = {
                    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3, "apr": 4, "april": 4,
                    "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7, "aug": 8, "august": 8, "sep": 9,
                    "sept": 9, "september": 9, "oct": 10, "october": 10, "nov": 11, "november": 11,
                    "dec": 12, "december": 12,
                }
                if mon_s in mon_map:
                    mnum = mon_map[mon_s]
                    dnum = int(d_s) if d_s else 1
                    try:
                        publication_date = datetime.date(y, mnum, dnum).isoformat()
                    except Exception:
                        publication_date = f"{y:04d}-{mnum:02d}-01"
                else:
                    publication_date = f"{y:04d}-01-01"

        authors = None
        al = rec.get("authors")
        if isinstance(al, list):
            out = []
            for a in al:
                if isinstance(a, dict) and isinstance(a.get("name"), str) and a.get("name").strip():
                    out.append(a["name"].strip())
            authors = out or None

        doi = None
        articleids = rec.get("articleids")
        if isinstance(articleids, list):
            for aid in articleids:
                if isinstance(aid, dict) and aid.get("idtype") == "doi" and isinstance(aid.get("value"), str):
                    doi = aid["value"]
                    break

        source_url = f"https://pubmed.ncbi.nlm.nih.gov/{pmid_n}/"

        # Try EFetch for abstract/keywords/mesh/pmc id
        abstract = None
        pmc_id = None
        mesh_terms = None
        keywords = None
        try:
            params2 = {"db": "pubmed", "id": pmid_n, "retmode": "xml"}
            url2 = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?" + urllib.parse.urlencode(params2)
            with urllib.request.urlopen(url2, timeout=20) as resp2:
                xml = resp2.read().decode("utf-8", "replace")
            # crude XML extraction without third-party libs
            m_abs = re.search(r"<Abstract>(.*?)</Abstract>", xml, flags=re.DOTALL | re.IGNORECASE)
            if m_abs:
                # concatenate AbstractText nodes
                texts = re.findall(r"<AbstractText[^>]*>(.*?)</AbstractText>", m_abs.group(1), flags=re.DOTALL | re.IGNORECASE)
                if texts:
                    def _strip_tags(s):
                        return re.sub(r"<[^>]+>", "", s).replace("\n", " ").strip()
                    abstract = "\n".join([_strip_tags(t) for t in texts if _strip_tags(t)])
            m_pmc = re.search(r"<ArticleId\s+IdType=\"pmc\">(PMC[0-9]+)</ArticleId>", xml, flags=re.IGNORECASE)
            if m_pmc:
                pmc_id = m_pmc.group(1)

            mts = re.findall(r"<DescriptorName[^>]*>(.*?)</DescriptorName>", xml, flags=re.DOTALL | re.IGNORECASE)
            if mts:
                def _strip_tags(s):
                    return re.sub(r"<[^>]+>", "", s).replace("\n", " ").strip()
                mesh_terms = [t for t in (_strip_tags(x) for x in mts) if t] or None

            kws = re.findall(r"<Keyword[^>]*>(.*?)</Keyword>", xml, flags=re.DOTALL | re.IGNORECASE)
            if kws:
                def _strip_tags(s):
                    return re.sub(r"<[^>]+>", "", s).replace("\n", " ").strip()
                keywords = [t for t in (_strip_tags(x) for x in kws) if t] or None
        except Exception:
            pass

        now = _now_iso()
        row = existing
        if row is None:
            row = {
                "id": _gen_id("art"),
                "pmid": pmid_n,
                "status": "available",
                "title": None,
                "abstract": None,
                "journal": None,
                "publication_date": None,
                "authors": None,
                "doi": None,
                "pmc_id": None,
                "mesh_terms": None,
                "keywords": None,
                "source_url": None,
                "raw_metadata": None,
                "last_fetched_at": None,
                "created_at": now,
                "updated_at": now,
            }
            articles.append(row)

        row["status"] = "available"
        row["title"] = title if isinstance(title, str) else row.get("title")
        row["abstract"] = abstract if abstract is not None else row.get("abstract")
        row["journal"] = journal if isinstance(journal, str) else row.get("journal")
        row["publication_date"] = publication_date if publication_date is not None else row.get("publication_date")
        row["authors"] = authors if authors is not None else row.get("authors")
        row["doi"] = doi if doi is not None else row.get("doi")
        row["pmc_id"] = pmc_id if pmc_id is not None else row.get("pmc_id")
        row["mesh_terms"] = mesh_terms if mesh_terms is not None else row.get("mesh_terms")
        row["keywords"] = keywords if keywords is not None else row.get("keywords")
        row["source_url"] = source_url
        row["raw_metadata"] = {"esummary": summ}
        row["last_fetched_at"] = now
        row["updated_at"] = now

        _save("articles.json", articles)
        return {"article": row, "meta": {"cached": False, "upstream_called": True}}

    except Exception as e:
        # Upsert/mark fetch_failed
        now = _now_iso()
        if existing is None:
            fail_row = {
                "id": _gen_id("art"),
                "pmid": pmid_n,
                "status": "fetch_failed",
                "title": None,
                "abstract": None,
                "journal": None,
                "publication_date": None,
                "authors": None,
                "doi": None,
                "pmc_id": None,
                "mesh_terms": None,
                "keywords": None,
                "source_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid_n}/",
                "raw_metadata": {"error": str(e)},
                "last_fetched_at": None,
                "created_at": now,
                "updated_at": now,
            }
            articles.append(fail_row)
        else:
            existing["status"] = "fetch_failed"
            existing["raw_metadata"] = {"error": str(e)}
            existing["updated_at"] = now
        _save("articles.json", articles)
        return _err("UPSTREAM_ERROR", "Failed to fetch PubMed metadata.", detail=str(e), pmid=pmid_n)

def download_pubmed_pdf(pmid, **_extra):
    import json, os, datetime, time, re, urllib.parse, urllib.request, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _today_utc():
        return datetime.datetime.utcnow().date()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and c.get("id")]
        if not actives:
            return None
        actives.sort(key=lambda r: (r.get("created_at") or "", r.get("id")))
        return actives[0]

    def _norm_pmid(x):
        if isinstance(x, int):
            if x <= 0:
                return None
            return str(x)
        if isinstance(x, str):
            s = x.strip()
            if not s:
                return None
            s2 = re.sub(r"\D", "", s)
            return s2 if s2 else None
        return None

    pmid_n = _norm_pmid(pmid)
    if not pmid_n or not re.fullmatch(r"[0-9]+", pmid_n):
        return _err("VALIDATION_ERROR", "pmid must be a valid PubMed identifier (digits-only).")

    clients = _load("api_clients.json")
    client = _pick_active_client(clients)
    if not client:
        return _err("UNAUTHORIZED", "No active client context is available to serve this request.")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.")

    pdfs = _load("pdf_downloads.json")

    # Quota: count pdf_downloads created today
    today = _today_utc()
    created_today = 0
    for d in pdfs:
        if not isinstance(d, dict):
            continue
        if d.get("client_id") != client["id"]:
            continue
        dt = _parse_dt(d.get("created_at"))
        if dt and dt.date() == today:
            created_today += 1
    limit = client.get("daily_pdf_limit")
    if isinstance(limit, int) and created_today >= limit:
        return _err("RATE_LIMIT", "Daily PDF download quota exceeded.", limit=limit, used=created_today)

    # Ensure PMID exists in PubMed (ESummary quick check)
    try:
        params = {"db": "pubmed", "id": pmid_n, "retmode": "json"}
        url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?" + urllib.parse.urlencode(params)
        with urllib.request.urlopen(url, timeout=20) as resp:
            body = resp.read().decode("utf-8", "replace")
        summ = json.loads(body) or {}
        result = (summ.get("result") or {})
        uids = result.get("uids") or []
        if not uids:
            return _err("NOT_FOUND", "PMID not found in PubMed.", pmid=pmid_n)
    except Exception as e:
        return _err("UPSTREAM_ERROR", "Failed to verify PMID in PubMed.", detail=str(e), pmid=pmid_n)

    # Resolve article_id if cached article exists
    articles = _load("articles.json")
    article_id = None
    pmc_id = None
    for a in articles:
        if isinstance(a, dict) and a.get("pmid") == pmid_n and a.get("id"):
            article_id = a.get("id")
            pmc_id = a.get("pmc_id") if isinstance(a.get("pmc_id"), str) else None
            break

    now = _now_iso()
    dl_id = _gen_id("pdf")
    row = {
        "id": dl_id,
        "client_id": client["id"],
        "pmid": pmid_n,
        "article_id": article_id,
        "status": "queued",
        "resolved_pdf_url": None,
        "http_status": None,
        "content_type": None,
        "file_sha256": None,
        "file_size_bytes": None,
        "storage_uri": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    pdfs.append(row)
    _save("pdf_downloads.json", pdfs)

    # queued -> fetching
    row["status"] = "fetching"
    row["updated_at"] = _now_iso()
    _save("pdf_downloads.json", pdfs)

    # Attempt to resolve a PDF URL (prefer PMC if pmc_id known)
    candidate_urls = []
    if pmc_id:
        # Common direct PDF endpoint
        candidate_urls.append(f"https://pmc.ncbi.nlm.nih.gov/articles/{pmc_id}/pdf/")
    # Fallback: PubMed "pmc" / "full text" resolution is non-trivial; try pubmed direct (often HTML, not PDF)
    candidate_urls.append(f"https://pubmed.ncbi.nlm.nih.gov/{pmid_n}/")

    final_status = "failed"
    http_status = None
    content_type = None
    resolved_url = None
    file_sha256 = None
    file_size = None
    error_message = None

    def _is_pdf_bytes(b):
        return isinstance(b, (bytes, bytearray)) and len(b) >= 5 and b[:5] == b"%PDF-"

    # Try each candidate; accept only confirmed PDF with size > 0
    for u in candidate_urls:
        try:
            req = urllib.request.Request(u, headers={"User-Agent": "pubmed-mcp-local/1.0"})
            with urllib.request.urlopen(req, timeout=25) as resp:
                resolved_url = resp.geturl()
                http_status = getattr(resp, "status", None)
                content_type = resp.headers.get("Content-Type")
                data = resp.read()
            if http_status is None:
                http_status = 200
            if http_status >= 400:
                error_message = f"HTTP {http_status}"
                continue
            if not data or len(data) <= 0:
                error_message = "Empty response."
                continue
            # Validate PDF by header or content-type
            ct_ok = isinstance(content_type, str) and "pdf" in content_type.lower()
            if not (ct_ok or _is_pdf_bytes(data)):
                # Not a PDF
                error_message = "Response was not a PDF."
                continue
            file_size = len(data)
            if file_size <= 0:
                error_message = "Downloaded file size was zero."
                continue
            file_sha256 = hashlib.sha256(data).hexdigest()
            final_status = "downloaded"
            break
        except urllib.error.HTTPError as he:
            resolved_url = resolved_url or u
            http_status = he.code
            content_type = he.headers.get("Content-Type") if he.headers else None
            if he.code == 404:
                final_status = "not_found"
            elif he.code in (401, 403):
                final_status = "forbidden"
            else:
                final_status = "failed"
            error_message = str(he)
            break
        except Exception as e:
            error_message = str(e)
            continue

    # Update terminal state
    row["resolved_pdf_url"] = resolved_url
    row["http_status"] = int(http_status) if isinstance(http_status, int) and 100 <= http_status <= 599 else None
    row["content_type"] = content_type if isinstance(content_type, str) else None
    row["updated_at"] = _now_iso()

    if final_status == "downloaded":
        row["status"] = "downloaded"
        row["file_sha256"] = file_sha256
        row["file_size_bytes"] = int(file_size) if isinstance(file_size, int) and file_size >= 0 else None
        row["error_message"] = None
        # storage_uri intentionally left null (no persistence layer in local store)
    else:
        # If we never got a definitive HTTP status and candidates exhausted, mark failed
        if final_status not in ("not_found", "forbidden", "failed"):
            final_status = "failed"
        row["status"] = final_status
        row["error_message"] = error_message or ("PDF not available." if final_status == "not_found" else "PDF fetch failed.")
        row["file_sha256"] = None
        row["file_size_bytes"] = None
        row["storage_uri"] = None

    _save("pdf_downloads.json", pdfs)
    return {"download": row}

def get_current_api_client(api_key, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    used_client_id = None

    def _log_and_return(payload):
        nonlocal status_code, used_client_id
        latency_ms = int((time.time() - t0) * 1000)
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_current_api_client",
            "client_id": used_client_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)
        return payload

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "api_key must be a non-empty string"))

    api_clients = _load("api_clients.json")
    if not isinstance(api_clients, list):
        api_clients = []

    # Authenticate: match either stored client-visible value (not present) OR id.
    # Store has only api_key_hash, so allow:
    #  - direct match if caller passes the stored value (client-visible in this datastore)
    #  - OR match by client id (allowed by contract)
    client = None
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key:
            client = c
            break
        if c.get("api_key_hash") == api_key:
            client = c
            break

    if not client:
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Invalid API key"))

    used_client_id = client.get("id")

    if client.get("status") == "deleted":
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Client is deleted"))

    # Compute today's usage (UTC day boundary)
    today = datetime.datetime.utcnow().date()
    day_start = datetime.datetime(today.year, today.month, today.day, tzinfo=datetime.timezone.utc)
    day_end = day_start + datetime.timedelta(days=1)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept both "...Z" and offset forms
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []
    pdf_downloads = _load("pdf_downloads.json")
    if not isinstance(pdf_downloads, list):
        pdf_downloads = []

    search_used = 0
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != used_client_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        if day_start <= dt < day_end:
            if r.get("tool_name") in ("search_pubmed_key_words", "search_pubmed_advanced"):
                search_used += 1

    pdf_used = 0
    for d in pdf_downloads:
        if not isinstance(d, dict):
            continue
        if d.get("client_id") != used_client_id:
            continue
        dt = _parse_dt(d.get("created_at"))
        if not dt:
            continue
        if day_start <= dt < day_end:
            pdf_used += 1

    # Metadata quota usage: count upstream calls. This datastore has no explicit operation log for metadata fetches,
    # so we derive a conservative proxy from articles.last_fetched_at "today".
    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []
    metadata_used = 0
    for a in articles:
        if not isinstance(a, dict):
            continue
        dt = _parse_dt(a.get("last_fetched_at"))
        if not dt:
            continue
        if day_start <= dt < day_end:
            metadata_used += 1

    entitlements = {
        "daily_search_limit": client.get("daily_search_limit"),
        "daily_metadata_limit": client.get("daily_metadata_limit"),
        "daily_pdf_limit": client.get("daily_pdf_limit"),
    }
    usage = {
        "day_start_utc": day_start.isoformat(),
        "day_end_utc": day_end.isoformat(),
        "search_requests_used": search_used,
        "metadata_fetches_used": metadata_used,
        "pdf_downloads_used": pdf_used
    }
    remaining = {
        "search_requests_remaining": None if not isinstance(entitlements.get("daily_search_limit"), int) else max(0, entitlements["daily_search_limit"] - search_used),
        "metadata_fetches_remaining": None if not isinstance(entitlements.get("daily_metadata_limit"), int) else max(0, entitlements["daily_metadata_limit"] - metadata_used),
        "pdf_downloads_remaining": None if not isinstance(entitlements.get("daily_pdf_limit"), int) else max(0, entitlements["daily_pdf_limit"] - pdf_used),
    }

    status_code = "ok"
    return _log_and_return({
        "api_client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "entitlements": entitlements,
        "usage_today": usage,
        "remaining_today": remaining
    })

def list_search_requests(api_key, status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    used_client_id = None

    def _log_and_return(payload):
        nonlocal status_code, used_client_id
        latency_ms = int((time.time() - t0) * 1000)
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "list_search_requests",
            "client_id": used_client_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)
        return payload

    # Validate input types/enums
    if not isinstance(api_key, str) or not api_key.strip():
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "api_key must be a non-empty string"))

    allowed_status = {"queued", "running", "succeeded", "failed"}
    if status is not None and status not in allowed_status:
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status))))

    allowed_tool = {"search_pubmed_key_words", "search_pubmed_advanced"}
    if tool_name is not None and tool_name not in allowed_tool:
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid tool_name", allowed=list(sorted(allowed_tool))))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer"))
    if limit < 1 or limit > 200:
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 200"))

    if cursor is not None and not isinstance(cursor, str):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "cursor must be a string or null"))

    def _parse_rfc3339(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 timestamp string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 timestamp string")

    created_after_dt, err = _parse_rfc3339(created_after, "created_after")
    if err:
        status_code = "error"
        return _log_and_return(err)
    created_before_dt, err = _parse_rfc3339(created_before, "created_before")
    if err:
        status_code = "error"
        return _log_and_return(err)

    # Authenticate
    api_clients = _load("api_clients.json")
    if not isinstance(api_clients, list):
        api_clients = []
    client = None
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if not client:
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Invalid API key"))

    used_client_id = client.get("id")
    if client.get("status") != "active":
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Client is not active"))

    # Cursor decode: base64url JSON {"created_at": "...", "id": "..."} meaning "start after this"
    start_after = None
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                raise ValueError("bad cursor")
            start_after = (str(obj["created_at"]), str(obj["id"]))
        except Exception:
            status_code = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor"))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    rows = _load("search_requests.json")
    if not isinstance(rows, list):
        rows = []

    # Filter ownership + optional filters
    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != used_client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        r_dt = _parse_dt(r.get("created_at"))
        if created_after_dt and (not r_dt or r_dt < created_after_dt):
            continue
        if created_before_dt and (not r_dt or r_dt >= created_before_dt):
            continue
        filtered.append(r)

    # Sort newest-first by created_at then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        # missing dates sort last
        ts = dt.timestamp() if dt else float("-inf")
        return (ts, str(r.get("id", "")))

    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if start_after is not None:
        ca, cid = start_after
        ca_dt = _parse_dt(ca)
        def _is_after(r):
            r_dt = _parse_dt(r.get("created_at"))
            if not ca_dt or not r_dt:
                return False
            if r_dt < ca_dt:
                return False
            if r_dt > ca_dt:
                return True
            return str(r.get("id", "")) > cid
        # We need items strictly "newer than" cursor in this sort order means items with (created_at,id) < cursor
        # Since sorted desc, we skip until we pass the cursor item.
        new_list = []
        passed = False
        for r in filtered:
            r_dt = _parse_dt(r.get("created_at"))
            r_pair = (r_dt.isoformat() if r_dt else "", str(r.get("id", "")))
            if not passed:
                if r_pair == (ca_dt.isoformat(), cid):
                    passed = True
                continue
            new_list.append(r)
        filtered = new_list

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_created = last.get("created_at")
        last_id = last.get("id")
        token = json.dumps({"created_at": last_created, "id": last_id}, ensure_ascii=False, separators=(",", ":"))
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8").rstrip("=")

    status_code = "ok"
    return _log_and_return({
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    })

