        return payload

    if include_results is None:
        include_results = False
    if results_limit is None:
        results_limit = 100

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "api_key must be a non-empty string"))
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "search_request_id must be a non-empty string"))
    if not isinstance(include_results, bool):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "include_results must be a boolean"))
    if not isinstance(results_limit, int) or results_limit < 1 or results_limit > 500:
