            break
    if not client:
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Invalid API key"))

    used_client_id = client.get("id")
    if client.get("status") != "active":
        status_code = "error"
        return _log_and_return(_err("UNAUTHORIZED", "Client is not active"))

    # Fetch request ensuring ownership
    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == search_request_id and r.get("client_id") == used_client_id:
            req = r
            break
    if not req:
        status_code = "error"
        return _log_and_return(_err("NOT_FOUND", "search_request not found"))

    out = {"search_request": req}

    if include_results:
        results = _load("search_results.json")
        if not isinstance(results, list):
            results = []
        hits = [x for x in results if isinstance(x, dict) and x.get("search_request_id") == search_request_id]
        hits.sort(key=lambda x: int(x.get("rank", 10**9)) if isinstance(x.get("rank"), int) else 10**9)
