def set_api_client_status(api_key, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0439000" if __import__("os").path.isdir("./environment_mix/0439000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_code, client_id=None, error=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{os.urandom(3).hex()}",
                "endpoint": "set_api_client_status",
                "client_id": client_id,
                "credential": api_key,
                "status": status_code,
                "error": error,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "api_key must be a non-empty string"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if not isinstance(status, str) or status not in {"active", "suspended", "deleted"}:
        _audit("error", None, {"code": "VALIDATION_ERROR", "message": "status must be one of: active, suspended, deleted"})
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []

    # Authenticate by matching api_key to stored client-visible api_key_hash (or id)
    idx = None
    for i, c in enumerate(clients):
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            idx = i
            break
    if idx is None:
        _audit("error", None, {"code": "UNAUTHORIZED", "message": "Invalid API key"})
        return _err("UNAUTHORIZED", "Invalid API key")

    client = clients[idx]
    cur = client.get("status")

    # FORBIDDEN if already deleted (per tool description; use UNAUTHORIZED code set doesn't include FORBIDDEN)
    if cur == "deleted":
        _audit("error", client.get("id"), {"code": "UNAUTHORIZED", "message": "Client is deleted"})
        return _err("UNAUTHORIZED", "Client is deleted")

    allowed = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set()
    }
    if cur not in allowed:
        _audit("error", client.get("id"), {"code": "VALIDATION_ERROR", "message": "Current client status is invalid", "current_status": cur})
        return _err("VALIDATION_ERROR", "Current client status is invalid", current_status=cur)

    if status == cur:
        # Do not return CONFLICT; accept and persist updated_at for real-world idempotency.
        client["updated_at"] = now
        clients[idx] = client
        _save("api_clients.json", clients)
        _audit("ok", client.get("id"), None)
        return {"api_client": client, "idempotent": True}

    if status not in allowed[cur]:
        _audit("error", client.get("id"), {"code": "INVALID_TRANSITION", "message": f"Invalid transition {cur} -> {status}", "from_status": cur, "to_status": status})
        return _err("INVALID_TRANSITION", f"Invalid transition {cur} -> {status}", from_status=cur, to_status=status)

    client["status"] = status
    client["updated_at"] = now
    clients[idx] = client
    _save("api_clients.json", clients)

    _audit("ok", client.get("id"), None)
    return {"api_client": client}
